function hasHangulText(value) {
  return Array.from(String(value)).some(ch => {
    const code = ch.codePointAt(0);
    return (code >= 0xAC00 && code <= 0xD7AF) ||
      (code >= 0x3130 && code <= 0x318F) ||
      (code >= 0x1100 && code <= 0x11FF);
  });
}

function getI18nText(lang, key, fallbackText) {
  const dict = TRANSLATIONS[lang] || {};
  const hasValue = Object.prototype.hasOwnProperty.call(dict, key);
  const value = hasValue ? dict[key] : undefined;

  if (!hasValue || value === undefined || value === null) {
    if (lang === "en") return "English translation pending.";
    if (lang === "ko" && fallbackText !== undefined && fallbackText !== null) return fallbackText;
    if (lang === "ko") return `번역 누락: ${key}`;

    const fallbackKo = TRANSLATIONS.ko && TRANSLATIONS.ko[key];
    if (fallbackKo !== undefined && fallbackKo !== null) return fallbackKo;

    const fallbackEn = TRANSLATIONS.en && TRANSLATIONS.en[key];
    if (fallbackEn !== undefined && fallbackEn !== null) return fallbackEn;

    return `Missing translation: ${key}`;
  }

  if (lang === "en" && hasHangulText(value)) {
    return "English translation pending.";
  }
  return value;
}

